INSERT INTO public.questions (language, level, category, question_type, question_text, options, correct_answer, explanation, image_url, audio_url, points, max_plays, order_hint, is_active) VALUES
('es','B1','grammar','mcq','Cuando ______ a casa, llámame por favor.','["llegues","llegas","llegarás","llegabas"]','llegues','Con valor de futuro, "cuando" exige el presente de subjuntivo.',NULL,NULL,1,5,100,true),
('es','B1','grammar','mcq','Si tuviera más tiempo, ______ un curso de español.','["haría","hago","haré","hacía"]','haría','Condición irreal en presente: imperfecto de subjuntivo más condicional simple.',NULL,NULL,1,5,101,true),
('es','B1','grammar','mcq','Le dije que ______ paciencia con el equipo.','["tuviera","tenga","tiene","tendrá"]','tuviera','Estilo indirecto en pasado: el subjuntivo pasa al imperfecto.',NULL,NULL,1,5,102,true),
('es','B1','grammar','mcq','No me acuerdo ______ su apellido.','["de","a","en","por"]','de','El verbo "acordarse" rige la preposición "de".',NULL,NULL,1,5,103,true),
('es','B1','grammar','mcq','Este informe es más completo ______ el anterior.','["que","como","de","a"]','que','Comparativo de superioridad: "más ... que".',NULL,NULL,1,5,104,true),
('es','B1','grammar','mcq','Llevo tres años ______ en esta empresa.','["trabajando","trabajado","trabajar","trabajo"]','trabajando','"Llevar" con duración se construye con gerundio.',NULL,NULL,1,5,105,true),
('es','B1','grammar','mcq','Aunque ______ cansado, terminó la reunión.','["estaba","esté","estuviera","estará"]','estaba','Se presenta un hecho real y pasado, por eso se usa el indicativo.',NULL,NULL,1,5,106,true),
('es','B1','grammar','mcq','¿Le has dado el documento a Marta? Sí, ya ______ he dado.','["se lo","le lo","la lo","se la"]','se lo','El pronombre "le" se convierte en "se" delante de "lo".',NULL,NULL,1,5,107,true),
('es','B2','grammar','mcq','No creo que ______ la verdad sobre lo ocurrido.','["haya dicho","ha dicho","dijo","dirá"]','haya dicho','Los verbos de opinión en negativo exigen subjuntivo.',NULL,NULL,1,5,110,true),
('es','B2','grammar','mcq','El proyecto ______ aprobado la semana pasada por el consejo.','["fue","estuvo","era","fuera"]','fue','Pasiva de acción con "ser" en indefinido.',NULL,NULL,1,5,111,true),
('es','B2','grammar','mcq','La empresa, ______ sede está en Madrid, abrirá una filial en Dakar.','["cuya","cuyo","que su","la cual"]','cuya','"Cuyo" concuerda con el sustantivo poseído: la sede.',NULL,NULL,1,5,112,true),
('es','B2','grammar','mcq','De haberlo sabido antes, ______ de otra manera.','["habría actuado","actuaría","había actuado","actuara"]','habría actuado','Condición irreal en pasado: condicional compuesto.',NULL,NULL,1,5,113,true),
('es','B2','grammar','mcq','Te llamo en cuanto ______ los resultados.','["tenga","tengo","tendré","tuviera"]','tenga','Acción futura tras nexo temporal: presente de subjuntivo.',NULL,NULL,1,5,114,true),
('es','B2','grammar','mcq','El informe se entregará ______ los plazos previstos.','["conforme a","conforme de","según a","de acuerdo"]','conforme a','La locución correcta es "conforme a".',NULL,NULL,1,5,115,true),
('es','B2','grammar','mcq','Por mucho que ______, no cambiará de opinión.','["insistas","insistes","insistirás","insistías"]','insistas','Valor concesivo orientado al futuro: subjuntivo.',NULL,NULL,1,5,116,true),
('es','B2','grammar','mcq','Me molesta que la gente ______ tarde a las reuniones.','["llegue","llega","llegará","llegaba"]','llegue','Los verbos de sentimiento con sujetos distintos exigen subjuntivo.',NULL,NULL,1,5,117,true),
('es','C1','grammar','mcq','Ojalá me ______ avisado antes; ahora ya es tarde.','["hubieras","habrías","habías","hubiste"]','hubieras','"Ojalá" con deseo imposible en el pasado pide pluscuamperfecto de subjuntivo.',NULL,NULL,1,5,120,true),
('es','C1','grammar','mcq','No fue sino hasta el final de la reunión ______ se abordó el asunto.','["cuando","que","donde","como"]','cuando','Estructura enfática de relativo con valor temporal.',NULL,NULL,1,5,121,true),
('es','C1','grammar','mcq','Se marchó sin que nadie ______ cuenta.','["se diera","se dio","se daba","se dará"]','se diera','"Sin que" exige siempre subjuntivo.',NULL,NULL,1,5,122,true),
('es','C1','grammar','mcq','Por más esfuerzos que ______ hecho, el resultado no habría cambiado.','["hubiera","había","habría","haya"]','hubiera','Concesiva irreal en el pasado: pluscuamperfecto de subjuntivo.',NULL,NULL,1,5,123,true),
('es','C1','grammar','mcq','El acuerdo entrará en vigor ______ sea ratificado por ambas partes.','["una vez que","una vez de","en cuanto de","a medida de"]','una vez que','La locución conjuntiva correcta es "una vez que".',NULL,NULL,1,5,124,true),
('es','C2','grammar','mcq','Quienquiera que ______ la propuesta deberá defenderla ante el comité.','["formule","formula","formulará","formulaba"]','formule','Los relativos indefinidos con valor eventual exigen subjuntivo.',NULL,NULL,1,5,130,true),
('es','C2','grammar','mcq','De no haber mediado el arbitraje, el conflicto ______ enquistado.','["se habría","se había","se ha","se hubo"]','se habría','Prótasis irreal con infinitivo compuesto y apódosis en condicional compuesto.',NULL,NULL,1,5,131,true),
('es','C2','grammar','mcq','Tan pronto como ______ la resolución, se notificará a las partes.','["se dicte","se dicta","se dictará","se dictaba"]','se dicte','Nexo temporal proyectado al futuro: subjuntivo.',NULL,NULL,1,5,132,true),
('es','C2','grammar','mcq','Poco faltó para que ______ el plazo sin respuesta alguna.','["venciera","venció","vencía","vencerá"]','venciera','"Faltar poco para que" rige subjuntivo.',NULL,NULL,1,5,133,true),
('es','C2','grammar','mcq','No por mucho madrugar ______ más temprano.','["amanece","amanezca","amanecerá","amanecía"]','amanece','Refrán fijado en presente de indicativo.',NULL,NULL,1,5,134,true);
